/**
 * /pages/MedicineDetail.jsx
 * ---------------------------------------------------------------------------
 * Nhận `id` từ url (route /medicine/:id với props: true).
 */

import React, { useEffect, useState } from 'react'
import { Card, Descriptions, Button, Space, Spin, Result, Tag } from 'antd'
import { ArrowLeftOutlined } from '@ant-design/icons'

import PageHeader from '@/components/PageHeader'
import api from '@/model/api'
import { useRouter, useRoute } from '@/router'
import { useI18n } from '@/lang'
import { formatCurrency, formatDate } from '@/utils'

const MedicineDetail = ({ id }) => {
  const router = useRouter()
  const route = useRoute()
  const { t } = useI18n()
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        // Demo: dùng mock, thực tế gọi: await api.medicineApi.detail(id)
        await new Promise((r) => setTimeout(r, 300))
        setData({
          id,
          code: `MED00${id}`,
          name: 'Paracetamol 500mg',
          unit: 'Hộp',
          price: 25000,
          expiry: '2026-12-31',
          status: 1,
          description: 'Giảm đau, hạ sốt. Dùng theo chỉ định của bác sĩ.',
        })
      } catch (e) {
        console.error(e)
      } finally {
        setLoading(false)
      }
    }
    load()
  }, [id])

  if (loading) {
    return (
      <div className="loading-center">
        <Spin size="large" />
      </div>
    )
  }

  if (!data) {
    return (
      <Result
        status="404"
        title={t('Không tìm thấy')}
        subTitle={t('Không có thuốc với id = {{id}}', { id })}
        extra={<Button onClick={() => router.push('/medicine')}>{t('Quay lại')}</Button>}
      />
    )
  }

  return (
    <>
      <PageHeader
        title={t('Chi tiết thuốc')}
        subtitle={`Route: ${route.path} — name: ${route.name} — params.id: ${route.params.id}`}
        extra={
          <Button icon={<ArrowLeftOutlined />} onClick={() => router.back()}>
            {t('Quay lại')}
          </Button>
        }
      />

      <Card size="small">
        <Descriptions column={{ xs: 1, sm: 2 }} bordered size="small">
          <Descriptions.Item label={t('Mã thuốc')}>{data.code}</Descriptions.Item>
          <Descriptions.Item label={t('Tên thuốc')}>{data.name}</Descriptions.Item>
          <Descriptions.Item label={t('Đơn vị')}>{data.unit}</Descriptions.Item>
          <Descriptions.Item label={t('Đơn giá')}>
            {formatCurrency(data.price)}
          </Descriptions.Item>
          <Descriptions.Item label={t('Hạn dùng')}>
            {formatDate(data.expiry)}
          </Descriptions.Item>
          <Descriptions.Item label={t('Trạng thái')}>
            {data.status === 1 ? (
              <Tag color="green">{t('Đang bán')}</Tag>
            ) : (
              <Tag color="red">{t('Ngừng bán')}</Tag>
            )}
          </Descriptions.Item>
          <Descriptions.Item label={t('Mô tả')} span={2}>
            {data.description}
          </Descriptions.Item>
        </Descriptions>

        <Space className="mt-16">
          <Button type="primary">{t('Chỉnh sửa')}</Button>
          <Button danger>{t('Xoá')}</Button>
        </Space>
      </Card>
    </>
  )
}

export default MedicineDetail
